/**
 * Rolls up closed-won opportunity revenue per account for the current calendar year.
 *
 * The class runs "with sharing" and the query runs in USER_MODE. Together they apply the
 * running user's record sharing, object permissions and field-level security.
 */
public with sharing class OpportunityRollupService {

    /**
     * Returns the sum of Amount over won opportunities closing in the current calendar year,
     * keyed by Account Id.
     *
     * Every requested (non-null) account Id is a key in the result. Accounts with no qualifying
     * opportunities, or whose qualifying opportunities all have a blank Amount, map to 0.
     * Ids that were not requested never appear as keys.
     *
     * @param accountIds the accounts to roll up
     * @return map of Account Id to won amount this year; empty map for null or empty input
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Copy the input so the caller's set is never changed, and drop any null element.
        Set<Id> ids = new Set<Id>(accountIds);
        ids.remove(null);
        if (ids.isEmpty()) {
            return result;
        }

        // Start every requested account at 0 so each one is always present and never null.
        for (Id accountId : ids) {
            result.put(accountId, 0);
        }

        // One aggregate query: the database computes the sums.
        // Clause order matters: WHERE, then WITH, then GROUP BY.
        for (AggregateResult ar : [
            SELECT AccountId accId, SUM(Amount) total
            FROM Opportunity
            WHERE AccountId IN :ids
                AND IsWon = true
                AND CloseDate = THIS_YEAR
            WITH USER_MODE
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('accId');
            Decimal total = (Decimal) ar.get('total');
            // SUM is null when every qualifying Amount is blank; keep that account at 0.
            if (accountId != null && result.containsKey(accountId) && total != null) {
                result.put(accountId, total);
            }
        }

        return result;
    }
}
