/**
 * Creates or updates NPSP partial soft credits for peer-to-peer fundraisers.
 *
 * For each request the contact ends up with:
 *  - exactly one OpportunityContactRole on the opportunity, with Role = request.role.
 *    An existing role, such as the NPSP "Household Member" role, is reused and
 *    re-labelled. Any duplicate roles are removed.
 *  - exactly one npsp__Partial_Soft_Credit__c on the opportunity. It is linked to that
 *    contact role and carries the requested amount and role name.
 *
 * The whole call is validated before any DML. Any invalid request throws
 * SoftCreditException and nothing is changed.
 *
 * DML is always done on new in-memory records holding only the Id and the fields
 * being changed, never on queried records.
 *
 * Governor usage for any batch size: 3 SOQL queries and at most 4 DML statements.
 */
public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ---------- Collect ids ----------
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req == null || req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Each request needs an opportunityId and a contactId.');
            }
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // ---------- SOQL 1: opportunities ----------
        Map<Id, Opportunity> opps = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        // ---------- Validate the whole call before any DML ----------
        for (SoftCreditRequest req : requests) {
            Opportunity opp = opps.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found or not accessible: ' + req.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c != null && opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException('Contact ' + req.contactId
                    + ' is the primary contact of opportunity ' + req.opportunityId
                    + ' and cannot receive a soft credit.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be a positive number (opportunity '
                    + req.opportunityId + ', contact ' + req.contactId + ').');
            }
            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException('Soft credit amount ' + req.amount
                    + ' exceeds the amount of opportunity ' + req.opportunityId + '.');
            }
        }

        // ---------- SOQL 2: existing contact roles ----------
        Map<String, List<OpportunityContactRole>> ocrsByKey = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
            ORDER BY CreatedDate ASC, Id ASC
        ]) {
            String k = key(ocr.OpportunityId, ocr.ContactId);
            if (!ocrsByKey.containsKey(k)) {
                ocrsByKey.put(k, new List<OpportunityContactRole>());
            }
            ocrsByKey.get(k).add(ocr);
        }

        // ---------- SOQL 3: existing partial soft credits ----------
        Map<String, List<npsp__Partial_Soft_Credit__c>> pscsByKey = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
            ORDER BY CreatedDate ASC, Id ASC
        ]) {
            String k = key(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!pscsByKey.containsKey(k)) {
                pscsByKey.put(k, new List<npsp__Partial_Soft_Credit__c>());
            }
            pscsByKey.get(k).add(psc);
        }

        // ---------- Plan the changes (only new in-memory records are used for DML) ----------
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();
        List<SObject> toDelete = new List<SObject>();
        List<SObject> ocrDeletes = new List<SObject>();

        // The contact role used by each request (same index as requests). Inserted
        // records receive their Id after the insert.
        List<OpportunityContactRole> keptOcrs = new List<OpportunityContactRole>();
        // The Id of the existing soft credit for each request (null means create a new one)
        List<Id> keptPscIds = new List<Id>();

        for (SoftCreditRequest req : requests) {
            String k = key(req.opportunityId, req.contactId);
            List<npsp__Partial_Soft_Credit__c> existingPscs = pscsByKey.containsKey(k)
                ? pscsByKey.get(k) : new List<npsp__Partial_Soft_Credit__c>();
            List<OpportunityContactRole> existingOcrs = ocrsByKey.containsKey(k)
                ? ocrsByKey.get(k) : new List<OpportunityContactRole>();

            // Keep the first soft credit and remove any duplicates.
            npsp__Partial_Soft_Credit__c keptPsc = existingPscs.isEmpty() ? null : existingPscs[0];
            for (Integer i = 1; i < existingPscs.size(); i++) {
                toDelete.add(new npsp__Partial_Soft_Credit__c(Id = existingPscs[i].Id));
            }

            // Choose which contact role to keep. Prefer the one the soft credit already
            // points to, then one that already has the requested role, then the oldest.
            OpportunityContactRole chosen = null;
            if (keptPsc != null && String.isNotBlank(keptPsc.npsp__Contact_Role_ID__c)) {
                for (OpportunityContactRole ocr : existingOcrs) {
                    if (String.valueOf(ocr.Id).left(15) == keptPsc.npsp__Contact_Role_ID__c.left(15)) {
                        chosen = ocr;
                        break;
                    }
                }
            }
            if (chosen == null) {
                for (OpportunityContactRole ocr : existingOcrs) {
                    if (ocr.Role == req.role) {
                        chosen = ocr;
                        break;
                    }
                }
            }
            if (chosen == null && !existingOcrs.isEmpty()) {
                chosen = existingOcrs[0];
            }

            OpportunityContactRole kept;
            if (chosen == null) {
                kept = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role,
                    IsPrimary = false
                );
                ocrsToInsert.add(kept);
            } else {
                kept = new OpportunityContactRole(Id = chosen.Id);
                if (chosen.Role != req.role) {
                    ocrsToUpdate.add(new OpportunityContactRole(Id = chosen.Id, Role = req.role));
                }
                for (OpportunityContactRole ocr : existingOcrs) {
                    if (ocr.Id != chosen.Id) {
                        ocrDeletes.add(new OpportunityContactRole(Id = ocr.Id));
                    }
                }
            }

            keptOcrs.add(kept);
            keptPscIds.add(keptPsc == null ? null : keptPsc.Id);
        }
        // Grouped by type: soft credits first, then contact roles
        toDelete.addAll(ocrDeletes);

        // ---------- DML ----------
        Savepoint sp = Database.setSavepoint();
        try {
            if (!ocrsToUpdate.isEmpty()) {
                update ocrsToUpdate;                                    // DML 1
            }
            if (!ocrsToInsert.isEmpty()) {
                insert ocrsToInsert;                                    // DML 2 (fills Ids in keptOcrs)
            }

            List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
            for (Integer i = 0; i < requests.size(); i++) {
                SoftCreditRequest req = requests[i];
                npsp__Partial_Soft_Credit__c psc;
                if (keptPscIds[i] == null) {
                    psc = new npsp__Partial_Soft_Credit__c(
                        npsp__Opportunity__c = req.opportunityId,
                        npsp__Contact__c = req.contactId
                    );
                } else {
                    psc = new npsp__Partial_Soft_Credit__c(Id = keptPscIds[i]);
                }
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Contact_Role_ID__c = keptOcrs[i].Id;
                pscsToUpsert.add(psc);
            }
            upsert pscsToUpsert;                                        // DML 3

            // Delete duplicates last, after every soft credit points at the kept role.
            if (!toDelete.isEmpty()) {
                delete toDelete;                                        // DML 4
            }
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }

    private static String key(Id oppId, Id contactId) {
        return String.valueOf(oppId) + '|' + String.valueOf(contactId);
    }
}
