/**
 * Turns an open NPSP donation (pledge) into a monthly installment plan.
 *
 * Paid and written-off payments are history and are never modified. All other payments
 * (unpaid and not written off) are replaced by a new schedule of equal monthly installments.
 * The last installment absorbs the rounding remainder.
 *
 * The class runs with sharing, and its queries and DML run in user mode, so the running
 * user's sharing, CRUD and FLS are enforced.
 */
public with sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // ---- Input validation (nothing is changed before these checks pass) ----
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('Number of payments must be at least 1.');
        }
        if (opportunityId == null) {
            throw new PaymentPlanException('An opportunity Id is required.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('A first payment date is required.');
        }

        Boolean multiCurrency = UserInfo.isMultiCurrencyOrganization();

        // Lock the opportunity so that concurrent schedule requests can't interleave.
        // The access level is supplied through the queryWithBinds parameter, so the query
        // string itself must not contain a WITH USER_MODE clause.
        String oppSoql = 'SELECT Id, Amount, IsClosed'
            + (multiCurrency ? ', CurrencyIsoCode' : '')
            + ' FROM Opportunity WHERE Id = :opportunityId LIMIT 1 FOR UPDATE';
        List<Opportunity> opps = (List<Opportunity>) Database.queryWithBinds(
            oppSoql,
            new Map<String, Object>{ 'opportunityId' => opportunityId },
            AccessLevel.USER_MODE
        );
        if (opps.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found or not accessible: ' + opportunityId);
        }
        Opportunity opp = opps[0];

        if (opp.IsClosed) {
            throw new PaymentPlanException('Cannot schedule installments on a closed opportunity.');
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Paid__c, npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
        ];

        Decimal settled = 0;
        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c p : existingPayments) {
            if (p.npe01__Paid__c == true || p.npe01__Written_Off__c == true) {
                settled += (p.npe01__Payment_Amount__c == null ? 0 : p.npe01__Payment_Amount__c);
            } else {
                toDelete.add(p);
            }
        }

        Decimal amount = (opp.Amount == null ? 0 : opp.Amount);
        Decimal outstanding = amount - settled;
        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'There is no outstanding amount to schedule (outstanding: ' + outstanding + ').'
            );
        }

        // ---- Build the new schedule ----
        Decimal installment = outstanding.divide(numberOfPayments, 2, RoundingMode.DOWN);
        Decimal lastInstallment = outstanding - (installment * (numberOfPayments - 1));

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            npe01__OppPayment__c p = new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = (i == numberOfPayments - 1) ? lastInstallment : installment,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            );
            if (multiCurrency) {
                p.put('CurrencyIsoCode', opp.get('CurrencyIsoCode'));
            }
            newPayments.add(p);
        }

        // ---- Apply changes atomically ----
        Savepoint sp = Database.setSavepoint();
        try {
            if (!toDelete.isEmpty()) {
                Database.delete(toDelete, true, AccessLevel.USER_MODE);
            }
            Database.insert(newPayments, true, AccessLevel.USER_MODE);
        } catch (Exception e) {
            Database.rollback(sp);
            throw new PaymentPlanException('Failed to schedule installments: ' + e.getMessage(), e);
        }

        return newPayments;
    }
}
