/**
 * Provides employee directory data respecting record sharing and
 * field-level security of the running user.
 */
public with sharing class EmployeeDirectoryService {

    /**
     * Returns FB_Employee__c records visible to the running user through sharing,
     * ordered by Name. Custom fields the user cannot read are not queried, so they
     * are absent from the returned records. Returns an empty list if the user
     * cannot read FB_Employee__c at all.
     */
    public static List<FB_Employee__c> getDirectory() {
        Schema.DescribeSObjectResult objDescribe = Schema.SObjectType.FB_Employee__c;
        if (!objDescribe.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        List<Schema.SObjectField> optionalFields = new List<Schema.SObjectField>{
            FB_Employee__c.Department__c,
            FB_Employee__c.Salary__c,
            FB_Employee__c.Personal_Email__c
        };

        List<String> selectFields = new List<String>{ 'Id', 'Name' };
        for (Schema.SObjectField field : optionalFields) {
            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            if (fieldDescribe.isAccessible()) {
                selectFields.add(fieldDescribe.getName());
            }
        }

        // Field names come only from compile-time tokens filtered by FLS,
        // so the query string contains no user input.
        String soql = 'SELECT ' + String.join(selectFields, ', ')
            + ' FROM FB_Employee__c ORDER BY Name ASC';

        // User mode enforces sharing, CRUD and FLS; only readable fields are selected.
        return (List<FB_Employee__c>) Database.query(soql, AccessLevel.USER_MODE);
    }
}
